using System.Diagnostics; namespace GodTreeXOwais.Infrastructure; public sealed record DoctorItem(string Name,bool Available,string Detail); public sealed class DoctorService{public async Task<IReadOnlyList<DoctorItem>> Scan(){var r=new List<DoctorItem>();foreach(var n in new[]{"git","dotnet","node","npm","python"}){try{using var p=Process.Start(new ProcessStartInfo("where.exe",n){RedirectStandardOutput=true,UseShellExecute=false,CreateNoWindow=true});var o=await p!.StandardOutput.ReadToEndAsync();await p.WaitForExitAsync();r.Add(new(n,p.ExitCode==0,o.Trim()));}catch(Exception e){r.Add(new(n,false,e.Message));}}return r;}}